class TestCalendarDataview(BloomerpDataviewTestCase):
    dataview_key = 'calendar'

    def test_creation_requires_a_route_and_add_permission(self) -> None:
        """Avoid exposing cell creation when either the model route or user add access is absent."""
        state = SimpleNamespace(model=Mock(), request=SimpleNamespace(user=Mock()), content_type=SimpleNamespace(pk=10))
        with patch("bloomerp.components.objects.dataviews.dataview.UserPolicyManager") as manager:
            manager.return_value.has_global_permission.return_value = False
            self.assertIsNone(_get_create_component_url(state, "inboxes=1"))
            manager.return_value.has_global_permission.return_value = True
            with patch("bloomerp.components.objects.dataviews.dataview.get_create_view_url", return_value="items_add"), patch(
                "bloomerp.components.objects.dataviews.dataview.reverse", side_effect=NoReverseMatch,
            ):
                self.assertIsNone(_get_create_component_url(state, "inboxes=1"))

    def mixed_renderer(self, mode: str = "month") -> CalendarDataviewRenderer:
        """Build a real renderer with readable independent datetime and date-only fields."""
        options = CalendarDataView(
            start_field="start", end_field="end", start_date_field="start_date",
            end_date_field="end_date", view_mode=mode,
        )
        fields = [SimpleNamespace(field=name, field_type=kind) for name, kind in (
            ("start", "DateTimeField"), ("end", "DateTimeField"),
            ("start_date", "DateField"), ("end_date", "DateField"),
        )]
        state = SimpleNamespace(
            options=options, model=Mock(), request=SimpleNamespace(user=Mock()),
            fields=SimpleNamespace(accessible_fields=[(field, False) for field in fields]),
            preference=SimpleNamespace(pk=1, name="Calendar", options={"calendar": options.dump_options()}),
        )
        renderer = CalendarDataviewRenderer(state)
        self.enterContext(patch.object(renderer, "_edit_permissions_for_object", return_value=(False, False)))
        return renderer

    def test_independent_date_pair_is_required(self) -> None:
        """Keep legacy calendars valid and require both new all-day date boundaries."""
        CalendarDataView(start_field="start")
        with self.assertRaises(ValidationError):
            CalendarDataView(start_date_field="start_date")
        with self.assertRaises(ValidationError):
            CalendarDataView(end_date_field="end_date")
        with self.assertRaises(ValidationError):
            CalendarDataView(start_field="start", start_date_field="start_date", end_date_field="end_date")

    def test_all_day_is_inferred_and_end_date_is_exclusive(self) -> None:
        """Render date-only events without a boolean flag or an extra day at the exclusive end."""
        renderer = self.mixed_renderer()
        event = SimpleNamespace(pk=1, start=None, end=None, start_date=date(2026, 10, 15), end_date=date(2026, 10, 17))
        with patch("bloomerp.dataviews.calendar.renderer.UserPolicyManager") as manager:
            manager.return_value.has_access_to_object.return_value = True
            events, _legend = renderer._build_events(
                [event], renderer.get_start_field(renderer.state.fields, renderer.options),
                renderer.get_end_field(renderer.state.fields, renderer.options), None,
            )
        self.assertEqual(len(events), 1)
        self.assertTrue(events[0]["all_day"])
        self.assertEqual(events[0]["end_date"], date(2026, 10, 16))
        for mode in ("day", "week", "month", "list"):
            grouped = renderer._group_events(events, mode, date(2026, 10, 15), date(2026, 10, 18))
            self.assertEqual(set(grouped), {"2026-10-15", "2026-10-16"})
        self.assertEqual(event.end_date, date(2026, 10, 17))

    def test_existing_default_preferences_pick_up_the_new_date_pair(self) -> None:
        """Apply newly declared date fields to older defaults while respecting an explicit opt-out."""
        renderer = self.mixed_renderer()
        configured = renderer.options
        renderer.options = configured.model_copy(update={"start_date_field": None, "end_date_field": None})
        stored = renderer.state.preference.options["calendar"]
        stored.pop("start_date_field")
        stored.pop("end_date_field")
        config = SimpleNamespace(model_view_settings=SimpleNamespace(default_dataviews=[configured.model_copy(update={"name": "Calendar"})]))
        with patch("bloomerp.dataviews.calendar.renderer.get_model_config", return_value=config):
            self.assertEqual([field.field for field in renderer._date_fields()], ["start_date", "end_date"])
            stored.update({"start_date_field": None, "end_date_field": None})
            self.assertEqual(renderer._date_fields(), (None, None))

    def test_overnight_datetime_events_remain_timed(self) -> None:
        """Split overnight meetings across day grids while retaining original edit boundaries."""
        renderer = self.mixed_renderer("week")
        start = datetime(2026, 10, 15, 23, tzinfo=timezone.get_current_timezone())
        event = SimpleNamespace(pk=1, start=start, end=start + timedelta(hours=2), start_date=None, end_date=None)
        events, _legend = renderer._build_events(
            [event], renderer.get_start_field(renderer.state.fields, renderer.options),
            renderer.get_end_field(renderer.state.fields, renderer.options), None,
        )
        self.assertEqual(len(events), 2)
        self.assertTrue(all(not item["all_day"] for item in events))
        self.assertEqual([item["duration_minutes"] for item in events], [60, 60])
        self.assertEqual(events[0]["start_ms"], events[1]["start_ms"])
        self.assertEqual(set(renderer._group_events(events, "week", date(2026, 10, 15), date(2026, 10, 16))), {
            "2026-10-15T23", "2026-10-16T00",
        })

    def test_unreadable_or_ambiguous_date_ranges_are_not_rendered(self) -> None:
        """Suppress incomplete or mixed pairs and dates denied by row-specific field access."""
        renderer = self.mixed_renderer()
        event = SimpleNamespace(pk=1, start=None, end=None, start_date=date(2026, 10, 15), end_date=date(2026, 10, 16))
        start_field = renderer.get_start_field(renderer.state.fields, renderer.options)
        end_field = renderer.get_end_field(renderer.state.fields, renderer.options)
        with patch("bloomerp.dataviews.calendar.renderer.UserPolicyManager") as manager:
            manager.return_value.has_access_to_object.return_value = False
            self.assertEqual(renderer._build_events([event], start_field, end_field, None)[0], [])
        event.end_date = None
        self.assertIsNone(renderer._event_fields(event, start_field, end_field))
        event.end_date = date(2026, 10, 16)
        event.start = datetime(2026, 10, 15, 9, tzinfo=timezone.get_current_timezone())
        self.assertIsNone(renderer._event_fields(event, start_field, end_field))

    def test_view_mode_saves_only_the_calendar_period(self) -> None:
        """Save each supported period without losing date fields or other dataview options."""
        preference = SimpleNamespace(
            options={"calendar": {"start_field": "start", "end_field": "end"}, "table": {"page_size": 20}},
            save=Mock(),
        )
        for mode in ("day", "week", "month", "year", "list"):
            with self.subTest(mode=mode):
                request = RequestFactory().post("/", {"view_mode": mode}, content_type="application/json")
                request.user = Mock()
                with patch("bloomerp.dataviews.calendar.renderer.PreferenceManager") as manager:
                    manager.return_value.can_manage.return_value = True
                    response = CalendarDataviewRenderer.handle_action(
                        "view-mode", request, SimpleNamespace(preference=preference)
                    )
                    manager.return_value.can_manage.assert_called_once_with(preference)
                self.assertEqual(response.status_code, 200)
                self.assertEqual(json.loads(response.content)["view_mode"], mode)
                self.assertEqual(preference.options["calendar"], {
                    "start_field": "start", "end_field": "end", "view_mode": mode,
                })
                self.assertEqual(preference.options["table"], {"page_size": 20})
                preference.save.assert_called_with(update_fields=["options"])

    def test_view_mode_rejects_invalid_values_without_saving(self) -> None:
        """Reject malformed JSON, unsupported periods, and invalid JSON value types."""
        for payload in ('{', '[]', '{}', '{"view_mode":"decade"}', '{"view_mode":[]}'):
            with self.subTest(payload=payload):
                preference = SimpleNamespace(options={}, save=Mock())
                request = RequestFactory().post("/", payload, content_type="application/json")
                request.user = Mock()
                with patch("bloomerp.dataviews.calendar.renderer.PreferenceManager") as manager:
                    manager.return_value.can_manage.return_value = True
                    response = CalendarDataviewRenderer.handle_action(
                        "view-mode", request, SimpleNamespace(preference=preference)
                    )
                self.assertEqual(response.status_code, 400)
                preference.save.assert_not_called()

    def test_view_mode_requires_post_and_preference_management(self) -> None:
        """Prevent reads and users without preference ownership from changing saved periods."""
        preference = SimpleNamespace(options={}, save=Mock())
        state = SimpleNamespace(preference=preference)
        request = RequestFactory().get("/")
        self.assertEqual(CalendarDataviewRenderer.handle_action("view-mode", request, state).status_code, 405)
        request = RequestFactory().post("/", {"view_mode": "month"}, content_type="application/json")
        request.user = Mock()
        with patch("bloomerp.dataviews.calendar.renderer.PreferenceManager") as manager:
            manager.return_value.can_manage.return_value = False
            self.assertEqual(CalendarDataviewRenderer.handle_action("view-mode", request, state).status_code, 403)
        preference.save.assert_not_called()

    def test_scalar_color_groups_remain_stable_across_filtering(self) -> None:
        """Keep ordinary scalar grouping reusable without any Inbox assumptions."""
        renderer = self.mixed_renderer()
        renderer.state.request = RequestFactory().get("/calendar/")
        renderer.state.request.user = Mock()
        renderer.state.model = SimpleNamespace(_meta=SimpleNamespace(get_field=Mock(side_effect=AttributeError)))
        field = SimpleNamespace(field="category")
        event = SimpleNamespace(pk=1, category="Planning")
        with patch("bloomerp.dataviews.calendar.renderer.UserPolicyManager") as manager:
            manager.return_value.has_access_to_object.return_value = True
            first = renderer._color_groups(event, field)
            second = renderer._color_groups(event, field)
            manager.return_value.has_access_to_object.return_value = False
            self.assertEqual(renderer._color_groups(event, field), [])
        self.assertEqual(first, second)
        self.assertEqual(first[0]["label"], "Planning")

